<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:18mm 20mm 17mm}*{box-sizing:border-box}body{margin:0;color:#111;font:11.5pt/1.55 Georgia,'Times New Roman',serif}.document-paper{width:auto;min-height:0;margin:0;padding:0}.document-header{text-align:center;line-height:1.35;page-break-inside:avoid}.document-header div:last-child{margin-top:3px;font-weight:bold}.document-logo{width:20mm;height:20mm;object-fit:contain;margin-bottom:3mm}.resident-photo{float:right;width:28mm;height:34mm;object-fit:cover;border:1px solid #777;margin:0 0 5mm 7mm}.document-paper h1{text-align:center;text-transform:uppercase;margin:13mm 0 10mm;font-size:17pt;line-height:1.25;page-break-after:avoid}.opening{margin:0 0 6mm;font-weight:bold}.document-body,.document-closing{line-height:1.7;text-align:justify}.document-body{margin-top:0}.document-closing{margin-top:8mm}.document-meta{clear:both;margin-top:9mm;padding-top:3mm;border-top:.4pt solid #aaa;font:9pt/1.45 'DejaVu Sans',sans-serif}.document-meta span{display:block}.signature{width:65mm;margin:20mm 0 0 auto;text-align:center;page-break-inside:avoid}.signature-line{min-height:7mm;border-bottom:.7pt solid #111;font-weight:bold;text-transform:uppercase}.signature div:last-child{margin-top:2mm;font-size:10pt}.document-paper footer{position:fixed;right:0;bottom:-10mm;left:0;padding-top:2mm;border-top:.4pt solid #bbb;text-align:center;font:7.5pt/1.3 'DejaVu Sans',sans-serif;color:#555}</style></head><body>@include('documents._paper')</body></html>
